var fs = require("fs");
var crypto = require("crypto");

// Writes a file in one step: to a temporary file next to it, renamed over it
// once written, so that nobody reads it half written. (The tmp package no
// longer creates files outside the system's temp folder.)
exports.writeFile = function(path, data, options, callback) {
    if (typeof options == "function")
        return exports.writeFile(path, data, null, options);

    options = typeof options == "string" ? { encoding: options } : Object.assign({}, options);
    options.flag = "wx";

    var tmpFile = path + "." + process.pid + "." + crypto.randomBytes(6).toString("hex") + ".tmp";
    fs.writeFile(tmpFile, data, options, function(err) {
        if (err) return callback(err);
        fs.rename(tmpFile, path, function(err) {
            if (err) fs.unlink(tmpFile, function() {});
            callback(err);
        });
    });
};
